UPDATE REWARD_ITEM SET
	RI_TYPE = #{type}, RI_NAME = #{name}, RI_C1 = #{c1}, RI_C2 = #{c2}, RI_C3 = #{c3}, RI_C4 = #{c4},
	RI_MIN = #{min,jdbcType=DOUBLE}, RI_MAX = #{max,jdbcType=DOUBLE}
WHERE RI_IDX = #{ri_idx}

UPDATE REWARD_LEDGER SET
	RL_DATE = #{date}, RL_WORKER_NO = #{worker_no}, RL_NAME = #{name}, RL_DEPT = #{dept}, RL_TITLE = #{title},
	RL_TYPE = #{type}, RL_ITEM = #{item}, RL_DETAIL = #{detail}, RL_AMOUNT = #{amount,jdbcType=DOUBLE}, RL_POINTS = #{points,jdbcType=DOUBLE},
	RL_APPROVER = #{approver}, RL_STATUS = #{status}
WHERE RL_IDX = #{rl_idx}
